# ── Đề 19: Trường THCS Thuận Thành số 1 (UBND phường Thuận Thành, Bắc Ninh), đề thi giữa học kì I năm học 2026–2027, môn Toán lớp 9 (nguồn Drive: thuan-thanh-1-bac-ninh.pdf) ──
# Ghi chú khi chép (đề 2026–2027, thêm 12/11/2026):
# Cấu trúc đề: I. TRẮC NGHIỆM 20 câu (5,0 điểm, mỗi câu 0,2 điểm) + II. TỰ LUẬN 4 bài (5,0 điểm: Bài 1 = 1,5; Bài 2 = 1,0; Bài 3 = 2,0; Bài 4 = 0,5). Thời gian 90 phút. Không có phần Đúng/Sai hay trả lời ngắn.
# Tổng số entry = 28: 20 choice (Câu 1–20) + 8 essay (Bài 1a, 1b, 1c; Bài 2; Bài 3a, 3b, 3c; Bài 4). Mỗi ý a/b/c của Bài 1 và Bài 3 là 1 entry riêng.
