# Câu 2: đề viết '∠BPQ = 14° và ∠BQA = 42°' nhưng theo hình thì các góc thực sự là ∠APB = 14° (tại P, giữa PB và PA) và ∠AQB = 42° (tại Q, giữa QB và QA); đã chép đúng như đề và nêu cách hiểu theo hình trong explanation. Đáp số 103,44 m ⇒ làm tròn hàng đơn vị là 103 m (A); phương án D '103,4 m' không phải làm tròn đến hàng đơn vị.
# Câu 16: trong bản đề, các phương án bị xếp lệch thứ tự (hiển thị A, C, B, D = 4, 8, 2, 3); đã sắp lại đúng thứ tự A. AH = 4, B. AH = 2, C. AH = 8, D. AH = 3 (nội dung các phương án giữ nguyên, đáp án vẫn là AH = 4 tức A).
