# Bài 2: hướng dẫn chấm gốc có lỗi chép: viết điều kiện '(x, y > 6)' và 'Hai người làm chung trong 6 giờ ... mỗi giờ làm được 1/6 công việc' trong khi đề cho 16 giờ (phương trình (1) đúng là 1/x + 1/y = 1/16 và hệ giải ra x = 24, y = 48 đúng); điều kiện đúng là x, y > 16. Đã sửa trong explanation và ghi LƯU Ý.
